import { useState, useEffect, useCallback } from "react";
import { creneauApi, disponibiliteApi } from "../api/api";
import StatsBar from "./StatsBar";
import { Badge, STATUS_CRENEAU } from "./Badges";

const SALLES = ["Salle A1", "Salle A2", "Salle B1", "Amphithéâtre"];

// ── Formulaire créneau ────────────────────────────────
function FormulaireCreneaux({ onCreated }) {
  const [form, setForm]         = useState({ date: "", heureDebut: "", dureeMinutes: "30", salle: "Salle A1" });
  const [loading, setLoading]   = useState(false);
  const [error, setError]       = useState(null);
  const [success, setSuccess]   = useState(false);

  const handleSubmit = async (e) => {
    e.preventDefault();
    if (!form.date || !form.heureDebut) { setError("Date et heure obligatoires."); return; }
    setLoading(true);
    setError(null);
    try {
      await creneauApi.creer({
        date: form.date,
        heureDebut: form.heureDebut + ":00",
        dureeMinutes: parseInt(form.dureeMinutes),
        salle: form.salle,
      });
      setForm({ date: "", heureDebut: "", dureeMinutes: "30", salle: "Salle A1" });
      setSuccess(true);
      setTimeout(() => setSuccess(false), 2500);
      onCreated();
    } catch (e) { setError(e.message); }
    finally { setLoading(false); }
  };

  return (
    <div style={{
      background: "var(--surface)", border: "1px solid var(--border2)",
      borderRadius: "var(--radius-lg)", padding: "20px",
      position: "sticky", top: 24,
    }}>
      <div style={{ fontSize: 14, fontWeight: 600, color: "var(--text)", marginBottom: 4 }}>
        Nouveau créneau
      </div>
      <div style={{ fontSize: 12, color: "var(--muted)", marginBottom: 16 }}>
        Définir une plage horaire pour une soutenance
      </div>

      {error && (
        <div style={{ background: "#fee2e2", border: "1px solid #ef4444", color: "#991b1b", borderRadius: 8, padding: "8px 12px", fontSize: 12, marginBottom: 12 }}>
          {error}
        </div>
      )}
      {success && (
        <div style={{ background: "#d1fae5", border: "1px solid #10b981", color: "#065f46", borderRadius: 8, padding: "8px 12px", fontSize: 12, marginBottom: 12, fontWeight: 500 }}>
          Créneau créé avec succès.
        </div>
      )}

      <form onSubmit={handleSubmit} style={{ display: "flex", flexDirection: "column", gap: 12 }}>
        <Field label="Date" input={
          <input type="date" value={form.date}
            onChange={e => setForm(p => ({ ...p, date: e.target.value }))}
            style={inputStyle} />
        } />
        <Field label="Heure de début" input={
          <input type="time" value={form.heureDebut}
            onChange={e => setForm(p => ({ ...p, heureDebut: e.target.value }))}
            style={inputStyle} />
        } />
        <Field label="Durée" input={
          <select value={form.dureeMinutes}
            onChange={e => setForm(p => ({ ...p, dureeMinutes: e.target.value }))}
            style={inputStyle}>
            <option value="20">20 minutes</option>
            <option value="30">30 minutes</option>
            <option value="45">45 minutes</option>
            <option value="60">60 minutes</option>
          </select>
        } />
        <Field label="Salle" input={
          <select value={form.salle}
            onChange={e => setForm(p => ({ ...p, salle: e.target.value }))}
            style={inputStyle}>
            {SALLES.map(s => <option key={s}>{s}</option>)}
          </select>
        } />
        <button type="submit" disabled={loading}
          style={{
            marginTop: 4, padding: "10px", borderRadius: 8,
            border: "none", background: "#3b82f6", color: "#fff",
            fontSize: 13, fontWeight: 600, cursor: "pointer",
            opacity: loading ? 0.6 : 1,
          }}>
          {loading ? "Création..." : "Créer le créneau"}
        </button>
      </form>
    </div>
  );
}

// ── Formulaire disponibilité ──────────────────────────
function FormulaireDisponibilite({ onSaved }) {
  const [form, setForm]       = useState({ professeurId: "", date: "", heureDebut: "", heureFin: "", disponible: "true" });
  const [loading, setLoading] = useState(false);
  const [error, setError]     = useState(null);
  const [success, setSuccess] = useState(false);

  const handleSubmit = async (e) => {
    e.preventDefault();
    if (!form.professeurId || !form.date || !form.heureDebut || !form.heureFin) {
      setError("Tous les champs sont obligatoires.");
      return;
    }
    setLoading(true);
    setError(null);
    try {
      await disponibiliteApi.enregistrer({
        professeur: { id: parseInt(form.professeurId) },
        date: form.date,
        heureDebut: form.heureDebut + ":00",
        heureFin: form.heureFin + ":00",
        disponible: form.disponible === "true",
      });
      setForm({ professeurId: "", date: "", heureDebut: "", heureFin: "", disponible: "true" });
      setSuccess(true);
      setTimeout(() => setSuccess(false), 2500);
      onSaved();
    } catch (e) { setError(e.message); }
    finally { setLoading(false); }
  };

  return (
    <div style={{
      background: "var(--surface)", border: "1px solid var(--border2)",
      borderRadius: "var(--radius-lg)", padding: "20px",
      position: "sticky", top: 24,
    }}>
      <div style={{ fontSize: 14, fontWeight: 600, color: "var(--text)", marginBottom: 4 }}>
        Enregistrer une disponibilité
      </div>
      <div style={{ fontSize: 12, color: "var(--muted)", marginBottom: 16 }}>
        Indiquer la disponibilité d'un professeur
      </div>

      {error && (
        <div style={{ background: "#fee2e2", border: "1px solid #ef4444", color: "#991b1b", borderRadius: 8, padding: "8px 12px", fontSize: 12, marginBottom: 12 }}>
          {error}
        </div>
      )}
      {success && (
        <div style={{ background: "#d1fae5", border: "1px solid #10b981", color: "#065f46", borderRadius: 8, padding: "8px 12px", fontSize: 12, marginBottom: 12, fontWeight: 500 }}>
          Disponibilité enregistrée.
        </div>
      )}

      <form onSubmit={handleSubmit} style={{ display: "flex", flexDirection: "column", gap: 12 }}>
        <Field label="ID Professeur" input={
          <input type="number" placeholder="ex: 2" value={form.professeurId}
            onChange={e => setForm(p => ({ ...p, professeurId: e.target.value }))}
            style={inputStyle} />
        } />
        <Field label="Date" input={
          <input type="date" value={form.date}
            onChange={e => setForm(p => ({ ...p, date: e.target.value }))}
            style={inputStyle} />
        } />
        <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 10 }}>
          <Field label="De" input={
            <input type="time" value={form.heureDebut}
              onChange={e => setForm(p => ({ ...p, heureDebut: e.target.value }))}
              style={inputStyle} />
          } />
          <Field label="À" input={
            <input type="time" value={form.heureFin}
              onChange={e => setForm(p => ({ ...p, heureFin: e.target.value }))}
              style={inputStyle} />
          } />
        </div>
        <Field label="Statut" input={
          <select value={form.disponible}
            onChange={e => setForm(p => ({ ...p, disponible: e.target.value }))}
            style={inputStyle}>
            <option value="true">Disponible</option>
            <option value="false">Indisponible</option>
          </select>
        } />
        <button type="submit" disabled={loading}
          style={{
            marginTop: 4, padding: "10px", borderRadius: 8,
            border: "none", background: "#3b82f6", color: "#fff",
            fontSize: 13, fontWeight: 600, cursor: "pointer",
            opacity: loading ? 0.6 : 1,
          }}>
          {loading ? "Enregistrement..." : "Enregistrer"}
        </button>
      </form>
    </div>
  );
}

// ── Carte créneau ─────────────────────────────────────
function CreneauCard({ creneau }) {
  const cfg = STATUS_CRENEAU[creneau.statut] || STATUS_CRENEAU.DISPONIBLE;
  return (
    <div style={{
      background: "var(--surface)",
      border: `1px solid ${cfg.border}`,
      borderLeft: `4px solid ${cfg.border}`,
      borderRadius: "var(--radius)", padding: "14px 18px",
      display: "flex", alignItems: "center", justifyContent: "space-between",
    }}>
      <div>
        <div style={{ fontSize: 13, fontWeight: 600, color: "var(--text)", marginBottom: 3 }}>
          {creneau.salle}
        </div>
        <div style={{ fontSize: 12, color: "var(--muted)", fontFamily: "'DM Mono', monospace" }}>
          {creneau.date} · {creneau.heureDebut} — {creneau.heureFin} · {creneau.dureeMinutes} min
        </div>
      </div>
      <Badge config={cfg} />
    </div>
  );
}

// ── Carte disponibilité d'un prof ─────────────────────
function DispoCard({ dispo }) {
  const isDisponible = dispo.disponible;
  const cfg = isDisponible ? STATUS_CRENEAU.DISPONIBLE : STATUS_CRENEAU.OCCUPE;
  return (
    <div style={{
      background: "var(--surface)",
      border: `1px solid ${cfg.border}`,
      borderLeft: `4px solid ${cfg.border}`,
      borderRadius: "var(--radius)", padding: "12px 16px",
      display: "flex", alignItems: "center", justifyContent: "space-between",
    }}>
      <div>
        <div style={{ fontSize: 12, color: "var(--muted)", fontFamily: "'DM Mono', monospace" }}>
          {dispo.date} · {dispo.heureDebut} — {dispo.heureFin}
        </div>
      </div>
      <Badge config={{ ...cfg, label: isDisponible ? "Disponible" : "Indisponible" }} />
    </div>
  );
}

// ── Composant principal ───────────────────────────────
export default function Disponibilites() {
  const [creneaux, setCreneaux]       = useState([]);
  const [dispos, setDispos]           = useState([]);
  const [loadingC, setLoadingC]       = useState(true);
  const [loadingD, setLoadingD]       = useState(false);
  const [profIdSearch, setProfIdSearch] = useState("");
  const [activeTab, setActiveTab]     = useState("creneaux");
  const [filterSalle, setFilterSalle] = useState("TOUT");
  const [filterStatut, setFilterStatut] = useState("TOUT");

  const loadCreneaux = useCallback(async () => {
    setLoadingC(true);
    try { setCreneaux(await creneauApi.getAll()); }
    catch (e) { console.error(e); }
    finally { setLoadingC(false); }
  }, []);

  const loadDispos = useCallback(async (id) => {
    if (!id) return;
    setLoadingD(true);
    try { setDispos(await disponibiliteApi.getParProf(id)); }
    catch (e) { setDispos([]); }
    finally { setLoadingD(false); }
  }, []);

  useEffect(() => { loadCreneaux(); }, [loadCreneaux]);

  const filteredCreneaux = creneaux.filter(c => {
    const salleOk  = filterSalle  === "TOUT" || c.salle  === filterSalle;
    const statutOk = filterStatut === "TOUT" || c.statut === filterStatut;
    return salleOk && statutOk;
  });

  const countDispo  = creneaux.filter(c => c.statut === "DISPONIBLE").length;
  const countOccupe = creneaux.filter(c => c.statut === "OCCUPE").length;

  const TABS = [
    { id: "creneaux",       label: "Créneaux de soutenance" },
    { id: "disponibilites", label: "Disponibilités des profs" },
  ];

  return (
    <div style={{ animation: "fadeIn 0.3s ease" }}>
      <style>{`
        @keyframes fadeIn { from { opacity:0; transform:translateY(8px) } to { opacity:1; transform:translateY(0) } }
        .tab-btn { transition: all 0.15s; cursor: pointer; }
        input[type="date"]::-webkit-calendar-picker-indicator,
        input[type="time"]::-webkit-calendar-picker-indicator { cursor: pointer; opacity: 0.6; }
      `}</style>

      <div style={{ marginBottom: 28 }}>
        <div style={{ fontSize: 11, color: "var(--muted)", textTransform: "uppercase", letterSpacing: "0.08em", marginBottom: 6 }}>
          Phase 2
        </div>
        <h1 style={{ fontSize: 24, fontWeight: 600, color: "var(--text)", letterSpacing: "-0.4px" }}>
          Disponibilités & Créneaux
        </h1>
      </div>

      <StatsBar stats={[
        { label: "Total créneaux", value: creneaux.length,  color: "#3b82f6" },
        { label: "Disponibles",    value: countDispo,  total: creneaux.length, color: "#10b981" },
        { label: "Occupés",        value: countOccupe, total: creneaux.length, color: "#f59e0b" },
      ]} />

      {/* Tabs */}
      <div style={{ display: "flex", gap: 2, borderBottom: "2px solid var(--border)", marginBottom: 24 }}>
        {TABS.map(t => (
          <button key={t.id} className="tab-btn"
            onClick={() => setActiveTab(t.id)}
            style={{
              padding: "10px 18px", border: "none", background: "none",
              fontSize: 13, fontWeight: activeTab === t.id ? 600 : 400,
              color: activeTab === t.id ? "#3b82f6" : "var(--muted)",
              borderBottom: activeTab === t.id ? "2px solid #3b82f6" : "2px solid transparent",
              marginBottom: -2,
            }}>
            {t.label}
          </button>
        ))}
      </div>

      {/* ── TAB CRÉNEAUX ── */}
      {activeTab === "creneaux" && (
        <div style={{ display: "grid", gridTemplateColumns: "1fr 300px", gap: 24, alignItems: "start" }}>
          <div>
            {/* Filtres */}
            <div style={{ display: "flex", gap: 8, marginBottom: 14, flexWrap: "wrap" }}>
              <select value={filterSalle} onChange={e => setFilterSalle(e.target.value)} style={{ ...inputStyle, width: "auto" }}>
                <option value="TOUT">Toutes les salles</option>
                {SALLES.map(s => <option key={s}>{s}</option>)}
              </select>
              <select value={filterStatut} onChange={e => setFilterStatut(e.target.value)} style={{ ...inputStyle, width: "auto" }}>
                <option value="TOUT">Tous les statuts</option>
                <option value="DISPONIBLE">Disponible</option>
                <option value="OCCUPE">Occupé</option>
              </select>
              <div style={{ fontSize: 12, color: "var(--muted)", display: "flex", alignItems: "center", marginLeft: 4 }}>
                {filteredCreneaux.length} créneau{filteredCreneaux.length !== 1 ? "x" : ""}
              </div>
            </div>

            {loadingC ? (
              <div style={{ display: "flex", flexDirection: "column", gap: 8 }}>
                {[1,2,3].map(i => (
                  <div key={i} style={{ height: 62, borderRadius: "var(--radius)", background: "var(--surface)", border: "1px solid var(--border)", opacity: 1 - i * 0.2 }} />
                ))}
              </div>
            ) : filteredCreneaux.length === 0 ? (
              <div style={{ textAlign: "center", padding: "48px 0", color: "var(--muted)" }}>
                Aucun créneau trouvé.
              </div>
            ) : (
              <div style={{ display: "flex", flexDirection: "column", gap: 8 }}>
                {filteredCreneaux.map(c => <CreneauCard key={c.id} creneau={c} />)}
              </div>
            )}
          </div>

          <FormulaireCreneaux onCreated={loadCreneaux} />
        </div>
      )}

      {/* ── TAB DISPONIBILITÉS ── */}
      {activeTab === "disponibilites" && (
        <div style={{ display: "grid", gridTemplateColumns: "1fr 300px", gap: 24, alignItems: "start" }}>
          <div>
            {/* Recherche par prof */}
            <div style={{ display: "flex", gap: 8, marginBottom: 20, alignItems: "center" }}>
              <input
                type="number"
                placeholder="ID du professeur (ex: 2)"
                value={profIdSearch}
                onChange={e => setProfIdSearch(e.target.value)}
                style={{ ...inputStyle, maxWidth: 240 }}
              />
              <button
                onClick={() => loadDispos(profIdSearch)}
                disabled={!profIdSearch || loadingD}
                style={{
                  padding: "8px 16px", borderRadius: 8,
                  border: "none", background: "#3b82f6", color: "#fff",
                  fontSize: 13, fontWeight: 600, cursor: "pointer",
                  opacity: !profIdSearch || loadingD ? 0.5 : 1,
                }}>
                {loadingD ? "Chargement..." : "Afficher"}
              </button>
            </div>

            {/* Résultats */}
            {!profIdSearch && (
              <div style={{
                textAlign: "center", padding: "48px 0", color: "var(--muted)",
                border: "1px dashed var(--border2)", borderRadius: "var(--radius-lg)",
              }}>
                Entrez l'ID d'un professeur pour voir ses disponibilités.
              </div>
            )}

            {profIdSearch && !loadingD && dispos.length === 0 && (
              <div style={{
                textAlign: "center", padding: "48px 0", color: "var(--muted)",
                border: "1px dashed var(--border2)", borderRadius: "var(--radius-lg)",
              }}>
                Aucune disponibilité enregistrée pour ce professeur.
              </div>
            )}

            {dispos.length > 0 && (
              <div>
                <div style={{ fontSize: 12, color: "var(--muted)", marginBottom: 10 }}>
                  {dispos.length} plage{dispos.length !== 1 ? "s" : ""} enregistrée{dispos.length !== 1 ? "s" : ""} — Prof. ID {profIdSearch}
                </div>
                <div style={{ display: "flex", flexDirection: "column", gap: 8 }}>
                  {dispos.map(d => <DispoCard key={d.id} dispo={d} />)}
                </div>
              </div>
            )}
          </div>

          <FormulaireDisponibilite onSaved={() => profIdSearch && loadDispos(profIdSearch)} />
        </div>
      )}
    </div>
  );
}

// ── Helpers ───────────────────────────────────────────
function Field({ label, input }) {
  return (
    <div style={{ display: "flex", flexDirection: "column", gap: 5 }}>
      <label style={{ fontSize: 11, color: "var(--muted)", textTransform: "uppercase", letterSpacing: "0.05em" }}>
        {label}
      </label>
      {input}
    </div>
  );
}

const inputStyle = {
  padding: "8px 12px", borderRadius: 8,
  border: "1px solid var(--border2)", background: "var(--surface2)",
  color: "var(--text)", outline: "none", fontSize: 13, width: "100%",
};
